def is_multiply_prime(a):
    """Check if a number is the product of exactly 3 prime numbers (allowing repeats).

    Args:
        a (int): The number to check (must be < 100).

    Returns:
        bool: True if a is the product of 3 primes, False otherwise.

    Examples:
        >>> is_multiply_prime(30)
        True
        >>> is_multiply_prime(10)
        False
        >>> is_multiply_prime(21)
        True
    """

    def is_prime(n):
        """Check if a number is prime."""
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    if a < 2:
        return False

    # Get all primes up to sqrt(a) for factorization
    primes = []
    for i in range(2, int(a**0.5) + 1):
        if is_prime(i):
            primes.append(i)

    # Factorize a into primes
    factors = []
    temp = a
    for p in primes:
        while temp % p == 0:
            factors.append(p)
            temp = temp // p
        if temp == 1:
            break

    # If remaining temp is a prime > sqrt(a), add it
    if temp > 2 and is_prime(temp):
        factors.append(temp)

    # Check if we have exactly 3 primes (allowing repeats)
    return len(factors) == 3 and all(is_prime(f) for f in factors)

