def decimal_to_binary(decimal):
    """Convert a decimal number to binary with 'db' prefixes and suffixes."""
    if decimal < 0:
        raise ValueError("Input must be a non-negative integer")

    binary_digits = []
    num = decimal

    # Handle zero case
    if num == 0:
        binary_digits.append('0')
    else:
        while num > 0:
            binary_digits.append('1' if num % 2 else '0')
            num = num // 2

    binary_str = ''.join(reversed(binary_digits))
    return f"db{binary_str}db"

