def compare_one(a, b):
    """
    Compare two variables representing real numbers and return the larger one in its original type.
    Return None if the values are equal after proper comparison.
    Handles cases where numbers are represented as strings with decimal separators (., or ,).
    """
    def normalize(value):
        """Normalize a value to a float, handling string representations with different decimal separators."""
        if isinstance(value, str):
            # Replace comma with dot for consistent float comparison
            normalized_str = value.replace(',', '.')
            return float(normalized_str)
        return float(value)

    # Normalize both inputs to float for comparison
    a_float = normalize(a)
    b_float = normalize(b)

    # Check if the normalized values are equal
    if a_float == b_float:
        return None

    # Determine the type of the larger value
    if isinstance(a, str) and isinstance(b, str):
        # Both are strings, return the one with the larger normalized value
        if a_float > b_float:
            return a
        else:
            return b
    elif isinstance(a, str):
        # a is string, b is not, return b if it's larger
        return b
    elif isinstance(b, str):
        # b is string, a is not, return a if it's larger
        return a
    else:
        # Both are not strings, return the one with the larger value
        if a_float > b_float:
            return a
        else:
            return b

